select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'One curie is equal to',
  '[{"id": "a", "text": "3.7 x 10 to the power 10 Bq"}, {"id": "b", "text": "1 Bq"}, {"id": "c", "text": "2.58 x 10 to the power -4 Bq"}, {"id": "d", "text": "3.7 x 10 to the power 7 Bq"}]'::jsonb, 'a', 'It was based on the activity of 1 g of radium-226.', 3,
  'science/fundamentals-of-nuclear-physics', 'q022'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'science' and d.slug = 'medical-physics' and c.slug = 'fundamentals-of-nuclear-physics' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'science/fundamentals-of-nuclear-physics' and k.depot_qid = 'q022')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'The radioactive decay law is N = N0 multiplied by',
  '[{"id": "a", "text": "e to the power minus lambda t"}, {"id": "b", "text": "one-half t"}, {"id": "c", "text": "e to the power lambda t"}, {"id": "d", "text": "lambda t"}]'::jsonb, 'a', 'N0 is the initial number of nuclei and lambda the decay constant.', 3,
  'science/fundamentals-of-nuclear-physics', 'q023'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'science' and d.slug = 'medical-physics' and c.slug = 'fundamentals-of-nuclear-physics' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'science/fundamentals-of-nuclear-physics' and k.depot_qid = 'q023')
order by c.id limit 1;

