insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'Assertion: The nucleus of a stable heavy atom has more neutrons than protons. Reason: Neutrons add attraction by the nuclear force without adding electrostatic repulsion.',
  '[{"id": "a", "text": "Both the assertion and the reason are true, and the reason is the correct explanation of the assertion"}, {"id": "b", "text": "Both the assertion and the reason are true, but the reason is not the correct explanation of the assertion"}, {"id": "c", "text": "The assertion is true but the reason is false"}, {"id": "d", "text": "The assertion is false but the reason is true"}, {"id": "e", "text": "Both the assertion and the reason are false"}]'::jsonb, 'a', 'Both are true and the reason explains the assertion. The stable line bends above N = Z for heavy nuclei.', 2,
  'science/fundamentals-of-nuclear-physics', 'q043'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'science' and d.slug = 'medical-physics' and c.slug = 'fundamentals-of-nuclear-physics' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'science/fundamentals-of-nuclear-physics' and k.depot_qid = 'q043')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'The ____ of a radioactive nuclide is the time taken for its activity to fall to one-half of its initial value.',
  '[{"id": "a", "text": "range"}, {"id": "b", "text": "decay constant"}, {"id": "c", "text": "mean life"}, {"id": "d", "text": "half-life"}]'::jsonb, 'd', 'The number of undecayed nuclei, and so the activity, falls by half in each half-life.', 3,
  'science/fundamentals-of-nuclear-physics', 'q044'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'science' and d.slug = 'medical-physics' and c.slug = 'fundamentals-of-nuclear-physics' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'science/fundamentals-of-nuclear-physics' and k.depot_qid = 'q044')
order by c.id limit 1;

insert into cgpa.keystone_questions
