insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'The first person to observe living microorganisms, using a single-lens microscope, was',
  '[{"id": "a", "text": "Antonie van Leeuwenhoek"}, {"id": "b", "text": "Robert Hooke"}, {"id": "c", "text": "Louis Pasteur"}, {"id": "d", "text": "Robert Koch"}]'::jsonb, 'a', 'Leeuwenhoek described living "animalcules" in the 1670s. Hooke drew the cells of cork with a compound microscope in 1665 but did not see living microbes. Pasteur and Koch worked two centuries later.', 1,
  'science/mcb101', 'q001'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'science' and d.slug = 'microbiology' and c.slug = 'mcb101' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'science/mcb101' and k.depot_qid = 'q001')
order by c.id limit 1;

insert into cgpa.keystone_questions
