select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'Louis Pasteur''s swan-neck flask experiments disproved',
  '[{"id": "a", "text": "spontaneous generation"}, {"id": "b", "text": "the germ theory of disease"}, {"id": "c", "text": "binomial nomenclature"}, {"id": "d", "text": "the existence of viruses"}]'::jsonb, 'a', 'Broth in a swan-neck flask stayed sterile until the neck was broken, showing microbes come from existing microbes in the air. The experiment supports the germ theory rather than disproving it.', 2,
  'science/mcb101', 'q002'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'science' and d.slug = 'microbiology' and c.slug = 'mcb101' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'science/mcb101' and k.depot_qid = 'q002')
order by c.id limit 1;

insert into cgpa.keystone_questions
