select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'Which structure stores genetic information in a bacterium besides the chromosome?',
  '[{"id": "a", "text": "Ribosome"}, {"id": "b", "text": "Plasmid"}, {"id": "c", "text": "Capsule"}, {"id": "d", "text": "Mesosome"}]'::jsonb, 'b', 'Plasmids carry extra genes such as resistance and virulence genes.', 2,
  'science/mcb201', 'q026'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'science' and d.slug = 'microbiology' and c.slug = 'mcb201' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'science/mcb201' and k.depot_qid = 'q026')
order by c.id limit 1;

