select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'Helper T cells carry the surface marker',
  '[{"id": "a", "text": "CD4"}, {"id": "b", "text": "CD34"}, {"id": "c", "text": "CD19"}, {"id": "d", "text": "CD8"}]'::jsonb, 'a', 'Helper T cells recognise antigen presented on MHC class II and release cytokines.', 2,
  'science/mcb401', 'q014'
from cgpa.courses c
