select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'The phenol ____ compares the killing power of a disinfectant with that of phenol under the same conditions.',
  '[{"id": "a", "text": "coefficient"}, {"id": "b", "text": "constant"}, {"id": "c", "text": "ratio"}, {"id": "d", "text": "index"}]'::jsonb, 'a', 'A value above 1 shows the disinfectant is more effective than phenol.', 3,
  'science/mcb405', 'q033'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'science' and d.slug = 'microbiology' and c.slug = 'mcb405' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'science/mcb405' and k.depot_qid = 'q033')
order by c.id limit 1;

