select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'The plane that divides the body into front and back parts is the',
  '[{"id": "a", "text": "transverse plane"}, {"id": "b", "text": "coronal (frontal) plane"}, {"id": "c", "text": "sagittal plane"}, {"id": "d", "text": "median plane"}]'::jsonb, 'b', 'Coronal CT and MRI images show the body from the front.', 2,
  'science/physiology-and-anatomy-for-medical-physics', 'q003'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
